  'mistakes-heading' => 'सामान्य वेब पीडीएफ गलतियाँ',
  'mistakes-p1' => 'बड़े गैर-अनुकूलित पीडीएफ़ को बिना संपीड़न के सीधे पृष्ठों में एम्बेड करने से प्रदर्शन धीमा हो जाता है। तैनाती से पहले हमेशा संपीड़ित करें।',
  'mistakes-p2' => 'ऐसी सामग्री के लिए पीडीएफ का उपयोग करना जो वेब पेज होनी चाहिए, पहुंच और उपयोगकर्ता अनुभव को कम कर देती है। वेब-सुलभ सामग्री के लिए वेब पेजों का उपयोग करें।',
  'mistakes-p3' => 'उन उपयोगकर्ताओं के लिए विकल्प प्रदान नहीं करना जो पीडीएफ़ डाउनलोड नहीं कर सकते या डाउनलोड नहीं करना पसंद करते हैं। हमेशा वेब विकल्प प्रदान करें.',
  'mistakes-p4' => 'मोबाइल उपकरणों पर परीक्षण करने में विफल रहने से मोबाइल अनुभव ख़राब हो जाता है। प्रकाशन से पहले हमेशा परीक्षण करें.',
  'mistakes-p5' => 'पहुंच-योग्यता सुविधाओं को लागू न करने से उपयोगकर्ता बाहर हो जाते हैं और कानूनी दायित्व बनता है। हमेशा पहुंच सुनिश्चित करें.',
  'alternatives-heading' => 'पीडीएफ विकल्प और एकीकरण',
  'alternatives-p1' => 'वेब पेजों के लिए उपयुक्त सामग्री के लिए, पीडीएफ़ के बजाय HTML का उपयोग करें। वेब पेज मोबाइल पर बेहतर काम करते हैं, तेजी से लोड होते हैं और अधिक पहुंच योग्य होते हैं।',
  'alternatives-p2' => 'जब पीडीएफ को अद्यतन करने की आवश्यकता होती है, तो __WORD_LINK__ आसान संपादन और पुनर्प्रकाशन सक्षम बनाता है। स्रोत दस्तावेज़ों को नियमित रूप से अद्यतन करके वेब-अनुकूलित पीडीएफ़ को अद्यतन रखें। इसी तरह, वेब गैलरी के लिए __IMAGES_LINK__ को तेजी से लोडिंग सुनिश्चित करने के लिए अनुकूलन प्रथाओं का पालन करना चाहिए।',
  'alternatives-p3' => 'दृश्य सामग्री प्रदर्शित करते समय पीडीएफ छवियों के बजाय प्रतिक्रियाशील छवियों का उपयोग करें।',
  'alternatives-p4' => 'रिपोर्ट, अनुबंध और औपचारिक दस्तावेज़ जैसे सटीक स्वरूपण को संरक्षित करने की आवश्यकता वाले दस्तावेज़ों के लिए पीडीएफ आरक्षित करें।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-p1' => 'वेब के लिए पीडीएफ को अनुकूलित करने से उपयोगकर्ता अनुभव, पहुंच और वेबसाइट के प्रदर्शन में सुधार होता है। संपीड़न, मोबाइल अनुकूलन और पहुंच सुविधाएँ पेशेवर वेब उपस्थिति बनाती हैं।',
  'conclusion-p2' => 'मौजूदा पीडीएफ़ को संपीड़ित करके और मोबाइल उपकरणों पर परीक्षण करके शुरुआत करें। सुगम्यता सुविधाओं को उत्तरोत्तर क्रियान्वित करें। अनुकूलन निर्णयों का मार्गदर्शन करने के लिए प्रदर्शन और उपयोगकर्ता व्यवहार की निगरानी करें।',
  'conclusion-p3' => 'उपयुक्त होने पर पीडीएफ को वेब-अनुकूल प्रारूप में परिवर्तित करने पर विचार करें। वेब-आधारित सामग्री के लिए वेब पेज अक्सर पीडीएफ़ की तुलना में बेहतर उपयोगकर्ता अनुभव प्रदान करते हैं।',
  'conclusion-p4' => 'पीडीएफ अनुकूलन को एक मानक अभ्यास बनाएं। प्रदर्शन और पहुंच में सुधार का संयोजन काफी बेहतर उपयोगकर्ता अनुभव बनाता है।',
);
